// Data Cleaning: tanggal -> YYYY-MM-DD, nominal -> angka saja, + match_key
const SOURCE = 'internal';
const BULAN = { jan:1, januari:1, feb:2, februari:2, mar:3, maret:3, apr:4, april:4, mei:5, may:5, jun:6, juni:6, jul:7, juli:7, agu:8, agt:8, aug:8, agustus:8, sep:9, september:9, okt:10, oct:10, oktober:10, nov:11, november:11, des:12, dec:12, desember:12 };
const pad = (n) => String(n).padStart(2, '0');

function findKey(row, patterns) {
  const keys = Object.keys(row);
  for (const p of patterns) {
    const k = keys.find((key) => key.toLowerCase().includes(p));
    if (k) return k;
  }
  return null;
}

function normDate(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') {
    // Serial number Google Sheets / Excel
    const d = new Date(Math.round((v - 25569) * 86400 * 1000));
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);
  if (m) return m[1] + '-' + pad(m[2]) + '-' + pad(m[3]);
  m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})/);
  if (m) {
    const y = m[3].length === 2 ? '20' + m[3] : m[3];
    return y + '-' + pad(m[2]) + '-' + pad(m[1]);
  }
  m = s.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})/);
  if (m && BULAN[m[2].toLowerCase()]) return m[3] + '-' + pad(BULAN[m[2].toLowerCase()]) + '-' + pad(m[1]);
  const d = new Date(s);
  if (!isNaN(d.getTime())) return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  return s;
}

function normAmount(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return Math.round(Math.abs(v));
  let s = String(v).trim();
  s = s.replace(/[.,]\d{2}$/, '');        // buang desimal ",00" / ".00"
  s = s.replace(/[^0-9]/g, '');            // hapus karakter non-numerik
  return s ? Number(s) : 0;
}

const out = [];
for (const item of $input.all()) {
  const row = item.json;
  if (!row || Object.keys(row).length === 0) continue;
  const dateKey = findKey(row, ['tanggal', 'tgl', 'date']);
  const amountKey = findKey(row, ['nominal', 'jumlah', 'amount', 'mutasi', 'debit', 'kredit', 'credit']);
  const descKey = findKey(row, ['keterangan', 'deskripsi', 'description', 'uraian', 'berita']);
  const tanggal = normDate(dateKey ? row[dateKey] : '');
  const nominal = normAmount(amountKey ? row[amountKey] : '');
  if (!tanggal && !nominal) continue;
  out.push({ json: {
    source: SOURCE,
    tanggal,
    nominal,
    keterangan: descKey ? String(row[descKey]) : '',
    match_key: tanggal + '_' + nominal,
  } });
}
return out;

