// Kelompokkan per match_key, lalu pasangkan internal vs bank
const groups = {};
for (const item of $input.all()) {
  const r = item.json;
  if (!r.match_key) continue;
  if (!groups[r.match_key]) groups[r.match_key] = { internal: [], bank: [] };
  if (r.source === 'internal') groups[r.match_key].internal.push(r);
  else groups[r.match_key].bank.push(r);
}

const out = [];
for (const key of Object.keys(groups)) {
  const g = groups[key];
  const pairs = Math.min(g.internal.length, g.bank.length);
  for (let i = 0; i < pairs; i++) {
    out.push({ json: {
      match_key: key, tanggal: g.internal[i].tanggal, nominal: g.internal[i].nominal,
      keterangan_internal: g.internal[i].keterangan, keterangan_bank: g.bank[i].keterangan,
      status: 'MATCHED', status_label: 'Matched (Cocok)',
    } });
  }
  for (let i = pairs; i < g.bank.length; i++) {
    out.push({ json: {
      match_key: key, tanggal: g.bank[i].tanggal, nominal: g.bank[i].nominal,
      keterangan_internal: '', keterangan_bank: g.bank[i].keterangan,
      status: 'UNRECORDED_INTERNAL', status_label: 'Unrecorded Internal (Ada di Bank, tidak ada di Internal)',
    } });
  }
  for (let i = pairs; i < g.internal.length; i++) {
    out.push({ json: {
      match_key: key, tanggal: g.internal[i].tanggal, nominal: g.internal[i].nominal,
      keterangan_internal: g.internal[i].keterangan, keterangan_bank: '',
      status: 'MISSING_IN_BANK', status_label: 'Missing in Bank (Ada di Internal, tidak ada di Bank)',
    } });
  }
}
out.sort((a, b) => a.json.tanggal.localeCompare(b.json.tanggal));
return out;

const rows = $input.all().map((i) => i.json);
const rp = (n) => 'Rp ' + Number(n).toLocaleString('id-ID');
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const unrecorded = rows.filter((r) => r.status === 'UNRECORDED_INTERNAL');
const missing = rows.filter((r) => r.status === 'MISSING_IN_BANK');

let text = '<b>LAPORAN REKONSILIASI - DITEMUKAN SELISIH</b>\n';
text += 'Total transaksi tidak cocok: ' + rows.length + '\n';
if (unrecorded.length) {
  text += '\n<b>Unrecorded Internal (Ada di Bank, tidak ada di Internal): ' + unrecorded.length + '</b>\n';
  for (const r of unrecorded) text += '- ' + r.tanggal + ' | ' + rp(r.nominal) + ' | ' + esc(r.keterangan_bank) + '\n';
}
if (missing.length) {
  text += '\n<b>Missing in Bank (Ada di Internal, tidak ada di Bank): ' + missing.length + '</b>\n';
  for (const r of missing) text += '- ' + r.tanggal + ' | ' + rp(r.nominal) + ' | ' + esc(r.keterangan_internal) + '\n';
}
if (text.length > 4000) text = text.slice(0, 3990) + '\n...';
return [{ json: { message: text, total_selisih: rows.length } }];
